@icontract.snapshot(lambda mimetype: mimetype.split(";")[0].strip() if mimetype and ";" in mimetype else mimetype, name="clean_mimetype")
@icontract.ensure(lambda mimetype, result: not result if not mimetype else True)
@icontract.ensure(lambda clean_mimetype, result: not clean_mimetype or result == (clean_mimetype == "application/json" or (clean_mimetype.startswith("application/") and clean_mimetype.endswith("+json"))))

@icontract.ensure(lambda mimetype, result: (not mimetype) <= (result == False), "Empty mimetype implies False result")
@icontract.ensure(lambda mimetype, result: not mimetype or not (get_mimetype(mimetype) == "application/json") or result == True, "application/json mimetype implies True result")
@icontract.ensure(lambda mimetype, result: not mimetype or not (get_mimetype(mimetype).startswith("application/") and get_mimetype(mimetype).endswith("+json")) or result == True, "application/*+json mimetype implies True result")
@icontract.ensure(lambda mimetype, result: not result or not mimetype or get_mimetype(mimetype) == "application/json" or (get_mimetype(mimetype).startswith("application/") and get_mimetype(mimetype).endswith("+json")), "True result only for valid JSON mimetypes")

@icontract.snapshot(lambda mimetype: get_mimetype(mimetype) if mimetype and ";" in mimetype else mimetype, name="cleaned_mimetype")
@icontract.ensure(lambda mimetype, result: mimetype or not result, "If mimetype is falsy, result must be False")
@icontract.ensure(lambda cleaned_mimetype, result: not result or cleaned_mimetype == "application/json" or (cleaned_mimetype and cleaned_mimetype.startswith("application/") and cleaned_mimetype.endswith("+json")), "If result is True, cleaned mimetype must be application/json or application/*+json pattern")
@icontract.ensure(lambda cleaned_mimetype, result: result or not cleaned_mimetype or (cleaned_mimetype != "application/json" and not (cleaned_mimetype.startswith("application/") and cleaned_mimetype.endswith("+json"))), "If result is False and mimetype exists, it must not match JSON patterns")

@icontract.snapshot(lambda mimetype: get_mimetype(mimetype) if (mimetype and ";" in mimetype) else mimetype, name="effective_mime")
@icontract.ensure(lambda mimetype, result: mimetype or not result, "Returns False for empty/None mimetype")
@icontract.ensure(lambda effective_mime, result: (effective_mime == "application/json") <= result, "Returns True for application/json")
@icontract.ensure(lambda effective_mime, result: not (effective_mime and effective_mime.startswith("application/") and effective_mime.endswith("+json")) or result, "Returns True for application/*+json pattern")
@icontract.ensure(lambda effective_mime, result: not result or (effective_mime == "application/json" or (effective_mime and effective_mime.startswith("application/") and effective_mime.endswith("+json"))), "Returns True only for valid JSON mimetypes")

@icontract.snapshot(lambda mimetype: get_mimetype(mimetype) if (mimetype and ";" in mimetype) else mimetype, name="effective_mimetype")
@icontract.ensure(lambda mimetype, result: not mimetype or result == (effective_mimetype == "application/json" or (effective_mimetype.startswith("application/") and effective_mimetype.endswith("+json"))))
@icontract.ensure(lambda result: isinstance(result, bool))
